import { revalidateTag, unstable_cache } from 'next/cache';
import { Suspense } from 'react';

// Mock function to simulate fetching product data from an upstream source (ERP/PIM)
// In a real app, this would query a database or external API.
const getProducts = unstable_cache(
  async () => {
    console.log('Fetching fresh product data from upstream...');
    // Simulate a slow fetch operation (e.g., 2 seconds)
    await new Promise((resolve) => setTimeout(resolve, 2000));

    // Return mock data with a timestamp to show freshness
    return Array.from({ length: 50 }, (_, i) => ({
      id: i + 1,
      name: `Product SKU-${1000 + i}`,
      price: (Math.random() * 100).toFixed(2),
      stock: Math.floor(Math.random() * 500),
      lastUpdated: new Date().toLocaleTimeString(),
    }));
  },
  ['products-list-cache-key'], // Key parts for the cache
  { 
    tags: ['products'], // Cache tag for invalidation
    revalidate: 3600    // Revalidate at most every hour (ISR)
  }
);

export default async function AdminProductsPage() {
  const products = await getProducts();

  async function syncCatalog() {
    'use server';
    console.log('Sync triggered by admin');
    // Invalidate the cache tag "products".
    // This marks the cached data as stale.
    // The next request will trigger a background revalidation (if supported)
    // or a blocking re-fetch depending on the hosting platform's ISR implementation.
    revalidateTag('products');
  }

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '5px 0', color: '#666', fontSize: '14px' }}>
            Data fetched at: {products[0]?.lastUpdated}
          </p>
        </div>

        {/* Sync Trigger Form */}
        <form action={syncCatalog}>
          <button 
            type="submit"
            style={{
              padding: '10px 16px',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontWeight: '500'
            }}
          >
            Sync Latest Catalog
          </button>
        </form>
      </header>

      <div style={{ border: '1px solid #eaeaea', borderRadius: '8px', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ backgroundColor: '#f7f7f7' }}>
            <tr>
              <th style={{ padding: '12px', borderBottom: '1px solid #eaeaea' }}>SKU Name</th>
              <th style={{ padding: '12px', borderBottom: '1px solid #eaeaea' }}>Price</th>
              <th style={{ padding: '12px', borderBottom: '1px solid #eaeaea' }}>Stock</th>
              <th style={{ padding: '12px', borderBottom: '1px solid #eaeaea' }}>Status</th>
