          </thead>
          <tbody>
            <Suspense fallback={<tr><td colSpan={4} style={{ padding: '12px' }}>Loading products...</td></tr>}>
              {products.map((product) => (
                <tr key={product.id} style={{ borderBottom: '1px solid #eaeaea' }}>
                  <td style={{ padding: '12px' }}>{product.name}</td>
                  <td style={{ padding: '12px' }}>${product.price}</td>
                  <td style={{ padding: '12px' }}>{product.stock}</td>
                  <td style={{ padding: '12px' }}>
                    <span style={{ 
                      padding: '4px 8px', 
                      borderRadius: '12px', 
                      fontSize: '12px',
                      backgroundColor: product.stock > 0 ? '#e6fffa' : '#fff5f5',
                      color: product.stock > 0 ? '#2c7a7b' : '#c53030'
                    }}>
                      {product.stock > 0 ? 'In Stock' : 'Out of Stock'}
                    </span>
                  </td>
                </tr>
              ))}
            </Suspense>
          </tbody>
        </table>
      </div>
    </div>
  );
}

